/**
 * markdown.ts — escape-first renderer for the safe markdown subset Max emits.
 *
 * TypeScript port of `public/markdown.js` from the max-grademaxxing project
 * (github.com/Cxsmxnaut/max-grademaxxing), preserving its behavior exactly.
 *
 * Safety: every piece of source text is HTML-escaped first, and every tag is
 * generated by this file. Model output can never introduce raw HTML, so a
 * hostile reply cannot inject scripts or markup.
 *
 * Covered: **bold**, *italic* / _italic_, ***bold italic***, ~~strike~~,
 * inline `code`, fenced code blocks, unordered and ordered lists, ###
 * headings, Markdown tables, > blockquotes, --- horizontal rules, KaTeX math
 * rendering (with LaTeX→symbol cleanup fallback), single-newline becomes <br>,
 * blank line starts a new paragraph.
 *
 * Math: $...$, $$...$$, \\( ... \\) and \\[ ... \\] are rendered by KaTeX with
 * `trust: false` (KaTeX escapes its own input and refuses \\href/\\htmlClass),
 * so math output is safe by construction like every other generated tag.
 * Anything KaTeX cannot parse falls back to the max-grademaxxing symbol
 * cleanup below, so students never see raw \\frac or $$ either way.
 */

import katex from 'katex';

export const mdEscape = (s: string) =>
	s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/**
 * Convert common LaTeX math sequences into clean readable symbols so even if a
 * model slips into $...$ or $$...$$ notation, students never see raw \frac or $$.
 */
function normalizeMath(raw: string) {
	const cleanExpr = (expr: string) =>
		expr
			.replace(
				/\\(?:left|right|big|Big|bigg|Bigg)\s*([()[\]{}|.])?/g,
				(_m, d: string | undefined) => (d === '.' ? '' : d || '')
			)
			.replace(/\\(?:text|textbf|mathbf|mathrm|mathit|boldsymbol|boxed)\{([^{}]*)\}/g, '$1')
			.replace(/\\frac\{([^{}]+)\}\{([^{}]+)\}/g, '($1) / ($2)')
			.replace(/\\ge(?:q)?\b/g, '≥')
			.replace(/\\le(?:q)?\b/g, '≤')
			.replace(/\\neq\b/g, '≠')
			.replace(/\\approx\b/g, '≈')
			.replace(/\\times\b/g, '×')
			.replace(/\\cdot\b/g, '·')
			.replace(/\\div\b/g, '÷')
			.replace(/\\pm\b/g, '±')
			.replace(/\\rightarrow\b|\\to\b|\\Rightarrow\b/g, '→')
			.replace(/(\d+%?)\s+arrow\s+(\d+%?)/gi, '$1 → $2')
			.replace(/\\%/g, '%')
			.replace(/\\\s+/g, ' ')
			.replace(/\\[,;:!]/g, ' ')
			.trim();

	return (
		raw
			// Display math $$...$$ or \[...\]
			.replace(/\$\$([\s\S]*?)\$\$/g, (_m, inner: string) => `\n\`${cleanExpr(inner)}\`\n`)
			.replace(/\\\[([\s\S]*?)\\\]/g, (_m, inner: string) => `\n\`${cleanExpr(inner)}\`\n`)
			// Inline \( ... \)
			.replace(/\\\(([^\n]*?)\\\)/g, (_m, inner: string) => cleanExpr(inner))
			// Inline $...$ — strip math delimiters when inner is a math expression or number
			.replace(/\$([^\s$][^$\n]*?[^\s$])\$/g, (_m, inner: string) => cleanExpr(inner))
			.replace(/\$([A-Za-z0-9])\$/g, '$1')
			// Also clean any stray LaTeX macros that leaked outside $...$
			.replace(
				/\\(?:left|right|big|Big|bigg|Bigg)\s*([()[\]{}|.])?/g,
				(_m, d: string | undefined) => (d === '.' ? '' : d || '')
			)
			.replace(
				/\\(?:text|textbf|mathbf|mathrm|mathit|boldsymbol|boxed)\{([^{}]*)\}/g,
				(_m, inner: string) => `**${inner.replace(/\\\s+/g, ' ').replace(/\\%/g, '%')}**`
			)
			.replace(/\\frac\{([^{}]+)\}\{([^{}]+)\}/g, '($1) / ($2)')
			.replace(/\\ge(?:q)?\b/g, '≥')
			.replace(/\\le(?:q)?\b/g, '≤')
			.replace(/\\approx\b/g, '≈')
			.replace(/\\rightarrow\b|\\to\b|\\Rightarrow\b/g, '→')
			.replace(/(\d+%?)\s+arrow\s+(\d+%?)/gi, '$1 → $2')
			.replace(/\\times\b/g, '×')
			.replace(/\\cdot\b/g, '·')
			.replace(/\\div\b/g, '÷')
	);
}

/**
 * Render one LaTeX expression via KaTeX. Returns null when KaTeX cannot parse
 * it so the caller can fall back to the readable-symbol cleanup — raw macros
 * must never reach the screen.
 */
function renderKatex(expr: string, displayMode: boolean): string | null {
	const trimmed = expr.trim();
	if (!trimmed) return null;
	try {
		return katex.renderToString(trimmed, {
			displayMode,
			throwOnError: true,
			trust: false, // no \\href / \\htmlClass / raw HTML, ever
			strict: false,
			output: 'html'
		});
	} catch {
		return null;
	}
}

const isTableRow = (line: string) => {
	const t = line.trim();
	return t.startsWith('|') && t.endsWith('|') && t.length > 2;
};

const isTableSeparator = (line: string) => {
	const t = line.trim();
	if (!t.startsWith('|') || !t.endsWith('|')) return false;
	const cells = t.slice(1, -1).split('|');
	return cells.length > 0 && cells.every((c) => /^\s*:?-{2,}:?\s*$/.test(c));
};

const splitTableCells = (line: string) =>
	line
		.trim()
		.replace(/^\|/, '')
		.replace(/\|$/, '')
		.split('|')
		.map((c) => c.trim());

// Placeholder sentinel: a private-use codepoint (not a control character, so
// lint accepts it in patterns) that mdEscape passes through untouched.
const SENTINEL = '\uE000';

export function renderMarkdown(src: unknown): string {
	// Strip any stray <think>...</think> blocks from reasoning models
	const rawSrc = String(src ?? '').replace(/<think>[\s\S]*?<\/think>\s*/gi, '');

	// fenced code blocks → placeholders (escaped at extraction)
	const fences: string[] = [];
	let text = rawSrc.replace(/```[a-z]*\n?([\s\S]*?)```/gi, (_m, code: string) => {
		fences.push('<pre><code>' + mdEscape(code.replace(/\n+$/, '')) + '</code></pre>');
		return SENTINEL + 'F' + (fences.length - 1) + SENTINEL;
	});

	// math → KaTeX placeholders. Extraction runs on the raw source (KaTeX
	// escapes its own input) before any markdown rewriting can touch the
	// expression. Display math stands alone as a block; unparseable math keeps
	// its original text and falls through to normalizeMath's symbol cleanup.
	const mathHtml: string[] = [];
	const stashMath = (expr: string, displayMode: boolean): string | null => {
		const html = renderKatex(expr, displayMode);
		if (html === null) return null;
		mathHtml.push(html);
		const token = SENTINEL + (displayMode ? 'D' : 'M') + (mathHtml.length - 1) + SENTINEL;
		// Display math is block-level: keep it on its own line so the block
		// parser promotes it out of the paragraph.
		return displayMode ? `\n${token}\n` : token;
	};
	text = text
		.replace(/\$\$([\s\S]*?)\$\$/g, (m, inner: string) => stashMath(inner, true) ?? m)
		.replace(/\\\[([\s\S]*?)\\\]/g, (m, inner: string) => stashMath(inner, true) ?? m)
		.replace(/\\\(([^\n]*?)\\\)/g, (m, inner: string) => stashMath(inner, false) ?? m)
		// Inline $...$ — bare money amounts ($5.00$) stay literal text
		.replace(/\$([^\s$][^$\n]*?[^\s$])\$/g, (m, inner: string) => {
			if (/^[\d,.]+$/.test(inner.trim())) {
				mathHtml.push(mdEscape(m));
				return SENTINEL + 'M' + (mathHtml.length - 1) + SENTINEL;
			}
			return stashMath(inner, false) ?? m;
		})
		.replace(/\$([A-Za-z0-9])\$/g, (m, inner: string) => stashMath(inner, false) ?? m);

	text = normalizeMath(text);
	text = mdEscape(text);

	// inline code → placeholders so emphasis never rewrites inside it
	const spans: string[] = [];
	text = text.replace(/`([^`\n]+)`/g, (_m, code: string) => {
		spans.push('<code>' + code + '</code>');
		return SENTINEL + 'C' + (spans.length - 1) + SENTINEL;
	});

	// emphasis, per line — runs before block parsing so it never touches the
	// tags we generate. Tight bounds keep "5 * 3 * 2" literal.
	const emphasize = (line: string) =>
		line
			.replace(/\*\*\*(?!\s)([^*]+?)(?<!\s)\*\*\*/g, '<strong><em>$1</em></strong>')
			.replace(/\*\*(?!\s)([^*]+?)(?<!\s)\*\*/g, '<strong>$1</strong>')
			.replace(/(^|[\s(])\*(?!\s)([^*\n]+?)(?<!\s)\*(?=$|[\s).,!?;:])/g, '$1<em>$2</em>')
			.replace(/(^|[\s(])_(?!\s)([^_\n]+?)(?<!\s)_(?=$|[\s).,!?;:])/g, '$1<em>$2</em>')
			.replace(/~~(?!\s)([^~]+?)(?<!\s)~~/g, '<del>$1</del>');

	const out: string[] = [];
	let list: 'ul' | 'ol' | null = null;
	let para: string[] = [];
	let quote: string[] = [];
	const flushPara = () => {
		if (para.length) {
			out.push('<p>' + para.join('<br>') + '</p>');
			para = [];
		}
	};
	const flushList = () => {
		if (list) {
			out.push('</' + list + '>');
			list = null;
		}
	};
	const flushQuote = () => {
		if (quote.length) {
			out.push('<blockquote><p>' + quote.join('<br>') + '</p></blockquote>');
			quote = [];
		}
	};
	const flushAll = () => {
		flushPara();
		flushList();
		flushQuote();
	};

	const lines = text.split('\n');
	for (let idx = 0; idx < lines.length; idx++) {
		const line = (lines[idx] ?? '').trimEnd();
		const trimmed = line.trim();
		if (!trimmed) {
			flushAll();
			continue;
		}

		// fence / display-math placeholders stand alone as blocks, never inside <p>
		if (new RegExp(`^${SENTINEL}[FD]\\d+${SENTINEL}$`).test(trimmed)) {
			flushAll();
			out.push(trimmed);
			continue;
		}

		// horizontal rule: ---, ***, ___
		if (/^(?:-{3,}|\*{3,}|_{3,})$/.test(trimmed)) {
			flushAll();
			out.push('<hr>');
			continue;
		}

		// markdown table: header row + |---|---| separator row
		if (isTableRow(trimmed) && idx + 1 < lines.length && isTableSeparator(lines[idx + 1] ?? '')) {
			flushAll();
			const headers = splitTableCells(trimmed);
			idx++; // skip separator line
			const rows: string[][] = [];
			while (idx + 1 < lines.length && isTableRow(lines[idx + 1] ?? '')) {
				idx++;
				rows.push(splitTableCells(lines[idx] ?? ''));
			}
			const thead =
				'<thead><tr>' +
				headers.map((h) => '<th>' + emphasize(h) + '</th>').join('') +
				'</tr></thead>';
			const tbody = rows.length
				? '<tbody>' +
					rows
						.map(
							(r) =>
								'<tr>' +
								headers.map((_, ci) => '<td>' + emphasize(r[ci] ?? '') + '</td>').join('') +
								'</tr>'
						)
						.join('') +
					'</tbody>'
				: '';
			out.push('<div class="table-wrap"><table>' + thead + tbody + '</table></div>');
			continue;
		}

		// blockquote: > text (escaped as &gt;)
		const bq = line.match(/^\s*&gt;\s?(.*)$/);
		if (bq) {
			flushPara();
			flushList();
			if ((bq[1] ?? '').trim()) quote.push(emphasize(bq[1] ?? ''));
			continue;
		}
		flushQuote();

		const heading = line.match(/^\s{0,3}#{1,6}\s+(.*)$/);
		if (heading) {
			flushAll();
			out.push('<h3>' + emphasize(heading[1] ?? '') + '</h3>');
			continue;
		}
		const ul = line.match(/^\s*[-*+]\s+(.*)$/);
		const ol = line.match(/^\s*\d+[.)]\s+(.*)$/);
		if (ul || ol) {
			flushPara();
			const kind = ul ? 'ul' : 'ol';
			if (list !== kind) {
				flushList();
				out.push('<' + kind + '>');
				list = kind;
			}
			out.push('<li>' + emphasize((ul ?? ol)?.[1] ?? '') + '</li>');
			continue;
		}
		flushList();
		para.push(emphasize(line));
	}
	flushAll();

	return out
		.join('')
		.replace(
			new RegExp(`${SENTINEL}C(\\d+)${SENTINEL}`, 'g'),
			(_m, i: string) => spans[Number(i)] ?? ''
		)
		.replace(
			new RegExp(`${SENTINEL}F(\\d+)${SENTINEL}`, 'g'),
			(_m, i: string) => fences[Number(i)] ?? ''
		)
		.replace(
			new RegExp(`${SENTINEL}[MD](\\d+)${SENTINEL}`, 'g'),
			(_m, i: string) => mathHtml[Number(i)] ?? ''
		);
}
